/**
* Renders a compact and functional set of pagination controls.
* Includes First, Previous, Next, Last buttons and a page input field.
*/
function renderPagination(containerId, totalItems, itemsPerPage, currentPage) {
    const container = document.getElementById(containerId);
    if (!container) {
        console.error(`Pagination container with ID "${containerId}" not found.`);
        return;
    }

    const totalPages = Math.ceil(totalItems / itemsPerPage);
    container.innerHTML = ''; // Clear old controls

    if (totalPages <= 1) {
        return; // No need for pagination.
    }

    // --- Determine button states ---
    const isFirstPage = currentPage === 1;
    const isLastPage = currentPage === totalPages;
    const commonButtonClasses = "px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-100";
    const disabledClasses = "opacity-50 cursor-not-allowed";

    // --- Build the HTML string ---
    let paginationHTML = `
        <div class="flex items-center gap-2">
            <!-- First Page Button -->
            <button data-page="1" 
                    class="${commonButtonClasses} ${isFirstPage ? disabledClasses : ''}" 
                    ${isFirstPage ? 'disabled' : ''}>
                First
            </button>
            <!-- Previous Page Button -->
            <button data-page="${currentPage - 1}" 
                    class="${commonButtonClasses} ${isFirstPage ? disabledClasses : ''}" 
                    ${isFirstPage ? 'disabled' : ''}>
                Previous
            </button>
        </div>

        <!-- Page number input and display -->
        <div class="flex items-center gap-2 text-sm text-gray-700">
            <span>Page</span>
            <input type="number" 
                   id="page-input" 
                   class="w-16 text-center border-gray-300 rounded-md shadow-sm focus:border-indigo-300 focus:ring focus:ring-indigo-200 focus:ring-opacity-50" 
                   value="${currentPage}" 
                   min="1" 
                   max="${totalPages}" 
                   aria-label="Current page">
            <span>of ${totalPages}</span>
        </div>

        <div class="flex items-center gap-2">
            <!-- Next Page Button -->
            <button data-page="${currentPage + 1}" 
                    class="${commonButtonClasses} ${isLastPage ? disabledClasses : ''}" 
                    ${isLastPage ? 'disabled' : ''}>
                Next
            </button>
            <!-- Last Page Button -->
            <button data-page="${totalPages}" 
                    class="${commonButtonClasses} ${isLastPage ? disabledClasses : ''}" 
                    ${isLastPage ? 'disabled' : ''}>
                Last
            </button>
        </div>
    `;

    container.innerHTML = paginationHTML;
}

/**
 * Fetches data from the API for a specific page and search term, then updates the UI.
 * This is the central function for all data updates.
 * @param {number} page The page number to fetch.
 * @param {string} searchTerm The search term to filter by.
 */
async function fetchAndRenderPage(tableConfig, page, searchTerm = '') {
    try {
        // --- 1. Call the API with pagination parameters ---
        // NOTE: Your loomeApi.runApiRequest must support passing parameters.
        // This is a hypothetical structure. Adjust it to how your API expects them.
        const apiParams = {
            "page": page,
            "pageSize": rowsPerPage,
            "search": searchTerm
        };
        // console.log(apiParams)
        // You might need to pass params differently, e.g., runApiRequest(10, apiParams)
        const response = await window.loomeApi.runApiRequest(API_GET_ALL_METADATA, apiParams);

        
        const parsedResponse = safeParseJson(response);
        // console.log(parsedResponse)

        // --- 2. Extract Data and Update State ---
        const dataForPage = parsedResponse.Results;
        const totalItems = parsedResponse.RowCount; // The TOTAL count from the server!
        currentPage = parsedResponse.CurrentPage;
        rowsPerPage = parsedResponse.PageSize;
        totalPages = Math.ceil(totalItems / rowsPerPage);
        
        // --- 3. Filter using searchTerm ---
        const lowerCaseSearchTerm = searchTerm.trim().toLowerCase();
        const filteredData = lowerCaseSearchTerm
            ? dataForPage.filter(item => 
                Object.values(item).some(value =>
                    String(value).toLowerCase().includes(lowerCaseSearchTerm)
                )
            )
        : dataForPage;

        // --- 4. Render the UI Components ---
        // Render the table with only the data for the current page
        renderTable(TABLE_CONTAINER_ID, tableConfig, filteredData, {
            renderAccordionContent: renderAccordionDetails 
        });

        // Render pagination using the TOTAL item count from the API
        renderPagination('pagination-controls', totalItems, rowsPerPage, currentPage);

        // Update the total count display
        const metaDataCount = document.getElementById('metaDataCount');
        if(metaDataCount) {
            metaDataCount.textContent = totalItems;
        }

    } catch (error) {
        console.error("Failed to fetch or render page:", error);
        const container = document.getElementById(TABLE_CONTAINER_ID);
        container.innerHTML = `<div class="p-4 text-red-600">Error loading data: ${error.message}</div>`;
    }
}


function renderTable(containerId, tableConfig, data, config = {}) {
    const container = document.getElementById(containerId);
    if (!container) {
        console.error(`Container with ID "${containerId}" not found.`);
        return;
    }
    const headers = tableConfig.headers;
    container.innerHTML = '';
    const table = document.createElement('table');
    table.className = 'w-full table-fixed divide-y divide-gray-200';
    
    // ... (thead creation is the same) ...
    const thead = document.createElement('thead');
    thead.className = 'bg-gray-50';
    const headerRow = document.createElement('tr');
    headers.forEach(headerConfig => {
        const th = document.createElement('th');
        th.scope = 'col';
        let thClasses = 'px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider ';
        if (headerConfig.widthClass) {
            thClasses += headerConfig.widthClass;
        }
        th.className = thClasses;
        th.textContent = headerConfig.label;
        headerRow.appendChild(th);
    });
    thead.appendChild(headerRow);
    table.appendChild(thead);


    const tbody = document.createElement('tbody');
    tbody.className = 'bg-white divide-y divide-gray-200';

    if (data.length === 0) {
        // ... (no data message is the same) ...
        const colSpan = headers.length || 1;
        tbody.innerHTML = `<tr><td colspan="${colSpan}" class="px-6 py-4 text-center text-sm text-gray-500">No data found.</td></tr>`;

    } else {
        data.forEach((item, index) => {
            const isAccordion = typeof config.renderAccordionContent === 'function';
            const triggerRow = document.createElement('tr');
            if (isAccordion) {
                triggerRow.className = 'accordion-trigger hover:bg-gray-50 cursor-pointer';
                // Use a more robust unique ID
                const accordionId = `accordion-content-${item.DataSourceID || index}`;
                triggerRow.dataset.target = `#${accordionId}`;
            }
            
            // ... (main row creation is the same) ...
            headers.forEach(headerConfig => {
                const td = document.createElement('td');
                let tdClasses = 'px-6 py-4 text-sm text-gray-800 ';
                if (headerConfig.className) {
                    tdClasses += headerConfig.className;
                } else {
                    tdClasses += 'whitespace-nowrap';
                }
                td.className = tdClasses;
                let cellContent;
                if (headerConfig.render) {
                    const value = headerConfig.key === 'actions' ? item : item[headerConfig.key];
                    cellContent = headerConfig.render(value);
                } else {
                    const value = item[headerConfig.key];
                    cellContent = value ?? 'N/A';
                }
                if (typeof cellContent === 'string' && cellContent.startsWith('<')) {
                    td.innerHTML = cellContent;
                } else {
                    td.textContent = cellContent;
                }
                triggerRow.appendChild(td);
            });
            tbody.appendChild(triggerRow);

            if (isAccordion) {
                const contentRow = document.createElement('tr');
                const accordionId = `accordion-content-${item.DataSourceID || index}`;
                contentRow.id = accordionId;
                contentRow.className = 'accordion-content hidden';
                
                const contentCell = document.createElement('td');
                contentCell.colSpan = headers.length;
                // The render function is called here with the full item, including 'Fields'
                contentCell.innerHTML = config.renderAccordionContent(item);
                
                contentRow.appendChild(contentCell);
                tbody.appendChild(contentRow);
            }
        });
    }
    table.appendChild(tbody);
    container.appendChild(table);

    // --- SIMPLIFIED Event Listener ---
    if (config.renderAccordionContent) {
        tbody.addEventListener('click', async (event) => {
            const trigger = event.target.closest('.accordion-trigger');
            const accordionBody = event.target.closest('.accordion-body');
            
            // --- Logic for Opening/Closing the Accordion ---
            if (trigger && !accordionBody) {
                event.preventDefault();
                const targetId = trigger.dataset.target;
                const contentRow = document.querySelector(targetId);
                if (contentRow) {
                    contentRow.classList.toggle('hidden');
                    trigger.classList.toggle('expanded');
                    const chevron = trigger.querySelector('.chevron-icon');
                    if (chevron) chevron.classList.toggle('rotate-180');
                }
                return;
            }

            // --- Logic for Edit/Save/Cancel Buttons (remains the same) ---
            const editButton = event.target.closest('.btn-edit');
            const saveButton = event.target.closest('.btn-save');
            const cancelButton = event.target.closest('.btn-cancel');
            const deleteButton = event.target.closest('.btn-delete');
            
            if (!editButton && !saveButton && !cancelButton && !deleteButton) return;
            event.stopPropagation();
            
            const parentAccordion = event.target.closest('.accordion-body');
            
            // const toggleEditState = (isEditing) => {
            //     parentAccordion.querySelectorAll('.view-state').forEach(el => el.classList.toggle('hidden', isEditing));
            //     parentAccordion.querySelectorAll('.edit-state').forEach(el => el.classList.toggle('hidden', !isEditing));

            //     // Enable/disable the accordion dropdown and its checkboxes based on editing state
            //     const menuButton = parentAccordion.querySelector('.accordion-dataSourceTypeDropdown');
            //     const inputs = parentAccordion.querySelectorAll('.accordion-dataSourceTypeMenu input[type="checkbox"]');
            //     if (isEditing) {
            //         if (menuButton) menuButton.removeAttribute('disabled');
            //         inputs.forEach(i => i.removeAttribute('disabled'));
            //     } else {
            //         if (menuButton) menuButton.setAttribute('disabled', '');
            //         inputs.forEach(i => i.setAttribute('disabled', ''));
            //     }
            // };
            
            // toggleEditState now accepts an optional `isCancel` flag. When entering edit mode
// we store original values on the accordion element; when cancelling we restore them.
            const toggleEditState = (isEditing, isCancel = false) => {
                // If entering edit mode, persist current view values so Cancel can restore them
                if (isEditing) {
                    const nameSpan = parentAccordion.querySelector('.view-state-name');
                    const descSpan = parentAccordion.querySelector('.view-state-description');
                    const isActiveSpan = parentAccordion.querySelector('.view-state-isactive');
                    parentAccordion.dataset.origName = nameSpan ? nameSpan.textContent : '';
                    parentAccordion.dataset.origDescription = descSpan ? descSpan.textContent : '';
                    parentAccordion.dataset.origIsActive = isActiveSpan ? isActiveSpan.textContent : '';

                    const menu = parentAccordion.querySelector('.accordion-dataSourceTypeMenu');
                    if (menu) {
                        const selected = Array.from(menu.querySelectorAll('input[type="checkbox"]'))
                            .filter(cb => cb.checked)
                            .map(cb => cb.value)
                            .join(',');
                        parentAccordion.dataset.origSelectedTypes = selected;
                    } else {
                        parentAccordion.dataset.origSelectedTypes = '';
                    }
                }

                // Toggle view/edit UI
                parentAccordion.querySelectorAll('.view-state').forEach(el => el.classList.toggle('hidden', isEditing));
                parentAccordion.querySelectorAll('.edit-state').forEach(el => el.classList.toggle('hidden', !isEditing));

                // Enable/disable the accordion dropdown and its checkboxes based on editing state
                const menuButton = parentAccordion.querySelector('.accordion-dataSourceTypeDropdown');
                const inputs = parentAccordion.querySelectorAll('.accordion-dataSourceTypeMenu input[type="checkbox"]');
                if (isEditing) {
                    if (menuButton) menuButton.removeAttribute('disabled');
                    inputs.forEach(i => i.removeAttribute('disabled'));
                } else {
                    // If this transition is due to Cancel, restore original values
                    if (isCancel) {
                        const origName = parentAccordion.dataset.origName || '';
                        const origDescription = parentAccordion.dataset.origDescription || '';
                        const origIsActive = parentAccordion.dataset.origIsActive || 'No';
                        const origSelectedTypes = parentAccordion.dataset.origSelectedTypes || '';

                        // Restore view-state text
                        const nameSpan = parentAccordion.querySelector('.view-state-name');
                        if (nameSpan) nameSpan.textContent = origName;
                        const descSpan = parentAccordion.querySelector('.view-state-description');
                        if (descSpan) descSpan.textContent = origDescription;
                        const isActiveSpan = parentAccordion.querySelector('.view-state-isactive');
                        if (isActiveSpan) isActiveSpan.textContent = origIsActive;

                        // Restore edit inputs values
                        const nameInput = parentAccordion.querySelector('.edit-state-name');
                        if (nameInput) nameInput.value = origName;
                        const descInput = parentAccordion.querySelector('.edit-state-description');
                        if (descInput) descInput.value = origDescription;
                        const isActiveInput = parentAccordion.querySelector('.edit-state-isactive');
                        if (isActiveInput) isActiveInput.checked = (origIsActive === 'Yes');

                        // Restore types checkboxes
                        if (inputs && inputs.length) {
                            const selectedSet = new Set(origSelectedTypes.split(',').filter(Boolean));
                            inputs.forEach(cb => { cb.checked = selectedSet.has(cb.value); });
                            // Trigger change so button text updates
                            const menu = parentAccordion.querySelector('.accordion-dataSourceTypeMenu');
                            if (menu) menu.dispatchEvent(new Event('change', { bubbles: true }));
                        }
                    }

                    if (menuButton) menuButton.setAttribute('disabled', '');
                    inputs.forEach(i => i.setAttribute('disabled', ''));

                    // Clear saved originals when leaving edit mode after a Save (not Cancel)
                    if (!isCancel) {
                        delete parentAccordion.dataset.origName;
                        delete parentAccordion.dataset.origDescription;
                        delete parentAccordion.dataset.origIsActive;
                        delete parentAccordion.dataset.origSelectedTypes;
                    }
                }
            };

            if (editButton) {
                toggleEditState(true);
                attachCharCounter(parentAccordion.querySelector('.edit-state-name'), 100);
                attachCharCounter(parentAccordion.querySelector('.edit-state-description'), 500);
            }

            if (saveButton) {
                // Stop the click from propagating and closing the accordion
                event.stopPropagation();
                
                // Get the button that was clicked and its parent accordion
                const saveBtn = saveButton;
                const accordionBody = saveBtn.closest('.accordion-body');
                const metaDataId = accordionBody.dataset.id; // Using .dataset.id
             
                // Show a "saving..." state for better UX
                saveBtn.textContent = 'Saving...';
                saveBtn.disabled = true;

                try {
                    // --- 1. Gather Data from the Form ---
                    // Use document.querySelector to find elements within the accordionBody
                    const rawName = accordionBody.querySelector('.edit-state-name').value;
                    const rawDesc = accordionBody.querySelector('.edit-state-description').value;
                    if (containsInvalidChars(rawName)) {
                        showToast('Special characters are not allowed in the Name.', 'error');
                        saveBtn.textContent = 'Save Changes'; saveBtn.disabled = false; return;
                    }
                    if (!rawName.trim()) {
                        showToast('Name is required.', 'error');
                        saveBtn.textContent = 'Save Changes'; saveBtn.disabled = false; return;
                    }
                    if (containsInvalidChars(rawDesc)) {
                        showToast('Special characters are not allowed in the Description.', 'error');
                        saveBtn.textContent = 'Save Changes'; saveBtn.disabled = false; return;
                    }
                    const updatedName = sanitizeInput(sanitizeStringForJson(rawName));
                    const updatedDescription = sanitizeInput(sanitizeStringForJson(rawDesc));
                    const updatedIsActive = !!accordionBody.querySelector('.edit-state-isactive').checked ? 1 : 0;


                    // --- 2. Send Request to the Endpoint using fetch ---
                    // Collect selected types from the accordion dropdown (if any)
                    const selectedTypes = Array.from(accordionBody.querySelectorAll('.accordion-dataSourceTypeMenu input[type="checkbox"]:checked'))
                        .map(cb => parseInt(cb.value, 10)).filter(v => !Number.isNaN(v));

                    // Validate required fields before sending
                    if (!updatedName || String(updatedName).trim() === '') {
                        throw new Error('Name is required.');
                    }

                    const updateParams = {
                        "meta_data_id": parseInt(metaDataId, 10),
                        "description":  updatedDescription,
                        "isActive":  updatedIsActive,
                        "name":  updatedName,
                        "dataSourceTypeIDs": selectedTypes
                    };
                    const updatedMetaData = await window.loomeApi.runApiRequest(API_UPDATE_METADATA, updateParams);
                    
                    // --- 3. Handle the Server's Response ---
                    if (!updatedMetaData) {
                        throw new Error('API call succeeded but returned no data.');
                    }
                    const updateParsed = safeParseJson(updatedMetaData);
                    const updateApiErr = extractApiError(updateParsed);
                    if (updateApiErr) throw new Error(updateApiErr);
                    // console.log(updatedMetaData)
                    showToast('MetaData edited successfully!\nPlease wait while the data refreshes.', 'success');

                    // --- 4. Update the UI with the New Data ---
                    accordionBody.querySelector('.view-state-name').textContent = updatedMetaData.Name;
                    accordionBody.querySelector('.view-state-description').textContent = updatedMetaData.Description;
                    accordionBody.querySelector('.view-state-isactive').textContent = updatedMetaData.IsActive ? 'Yes' : 'No';


                    // Finally, switch back to view mode by calling your existing function
                    toggleEditState(false);

                    setTimeout(() => {
                        // This code will run AFTER the 3-second delay
                        searchInput.value = '';
                        fetchAndRenderPage(tableConfig, 1, '');
                    }, 3000);

                } catch (error) {
                    console.error('Failed to save:', error);
                    showToast(`Error: ${error.message || 'Failed to save data.'}`, 'error');
                } finally {
                    // Reset the button back to its original state
                    saveBtn.textContent = 'Save Changes';
                    saveBtn.disabled = false;
                }
            }

            // if (cancelButton) toggleEditState(false);
            if (cancelButton) toggleEditState(false, true);

            if (deleteButton) {
                // Implement delete functionality here, similar to save but with a confirmation step
                const confirmDelete = confirm("Are you sure you want to delete this Meta Data item? This action cannot be undone.");
                if (!confirmDelete) return; 

                try {
                    const metaDataID = deleteButton?.dataset?.metaid || accordionBody?.dataset?.id;
                    const params = { meta_data_id : parseInt(metaDataID, 10) };
                    // Use the low-level runApiRequest so we can inspect error payloads directly
                    const raw = await window.loomeApi.runApiRequest(API_CANCEL_METADATA, params);
                    const parsed = safeParseJson(raw);

                    // If the API responded with a detail message, treat it as an error
                    if (parsed && parsed.detail) {
                        showToast(parsed.detail, 'error');
                        return;
                    }

                    // Some APIs may return a truthy success value or empty array; consider that success
                    showToast('Meta Data deleted successfully.', 'success');
                    setTimeout(() => window.location.reload(), 700);
                } catch (err) {
                    // Prefer API `detail` when available in thrown error objects
                    let detailMsg = 'Failed to delete Meta Data.';
                    try {
                        if (err && typeof err === 'object') {
                            if (err.detail) detailMsg = err.detail;
                            else if (err.response) {
                                const parsed = safeParseJson(err.response);
                                detailMsg = parsed && parsed.detail ? parsed.detail : (err.message || JSON.stringify(err));
                            } else {
                                detailMsg = err.message || JSON.stringify(err);
                            }
                        } else if (typeof err === 'string') {
                            detailMsg = err;
                        }
                    } catch (e) {
                        detailMsg = 'Failed to delete Meta Data.';
                    }
                    showToast(detailMsg, 'error');
                }
            }
        });
    }
}

function formatDate(inputDate) {
    // Log what the function receives
    // console.log(`formatDate received:`, inputDate, `(type: ${typeof inputDate})`);

    if (!inputDate) {
        // This will be triggered if inputDate is null, undefined, or an empty string ""
        return 'N/A'; 
    }

    const date = new Date(inputDate);
    
    if (isNaN(date.getTime())) {
        // This will be triggered if the date string is invalid, e.g., "hello world"
        console.warn(`Could not parse invalid date:`, inputDate);
        return 'N/A';
    }
    
    const formattingOptions = {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    };
    
    // The only way this returns undefined is if the function exits before this line.
    return date.toLocaleDateString('en-US', formattingOptions);
}

// --- Delegated handlers for accordion dropdowns ---
// Toggle checkbox when clicking the dropdown item and update button text on change.
document.addEventListener('click', (event) => {
    const item = event.target.closest('.accordion-ds-item');
    if (!item) return;
    event.preventDefault();
    // Prevent dropdown from closing by stopping propagation already done on click
    const checkbox = item.querySelector('input[type="checkbox"]');
    if (checkbox) {
        checkbox.checked = !checkbox.checked;
        checkbox.dispatchEvent(new Event('change', { bubbles: true }));
    }
});

document.addEventListener('change', (event) => {
    const changed = event.target.closest('.accordion-dataSourceTypeMenu');
    if (!changed) return;
    // Find the related button for this menu
    const menu = event.target.closest('.accordion-dataSourceTypeMenu');
    if (!menu) return;
    const metaId = menu.dataset.metaid;
    const button = document.getElementById(`dataSourceTypeDropdown-${metaId}`);
    if (!button) return;

    // Map selected checkbox values (IDs) to names using our lookup map
    const selectedNames = Array.from(menu.querySelectorAll('input[type="checkbox"]'))
        .filter(cb => cb.checked)
        .map(cb => dataSourceTypeIdToName.get(String(cb.value)) || String(cb.value));

    if (selectedNames.length === 0) {
        button.textContent = 'Select Types';
    } else if (selectedNames.length <= 2) {
        button.textContent = selectedNames.join(', ');
    } else {
        button.textContent = `${selectedNames.length} types selected`;
    }
});

