/**
 * Fetches ALL DataSourceTypes from the paginated API.
 * This is a self-contained function that returns the results.
 * @param {number} [pageSize=100] - The number of items per page.
 * @returns {Promise<Array>} A promise that resolves to an array of all data source types.
 */
async function getAllDataSourceTypes(pageSize = 100) {

    let allResults = []; // Use a local variable to store results

    try {
        // --- 1. Initial request ---
        const initialParams = { "page": 1, "pageSize": pageSize, "search": '' };
        const initialResponse = await window.loomeApi.runApiRequest(API_DATASOURCETYPE_ID, initialParams);
        const parsedInitial = safeParseJson(initialResponse);

        if (!parsedInitial || parsedInitial.RowCount === 0) {
            // console.log("No data source types found.");
            return []; // Return an empty array if there's no data
        }

        allResults = parsedInitial.Results;
        const totalPages = parsedInitial.PageCount;

        // If only one page, we're done
        if (totalPages <= 1) {
            return allResults;
        }

        // --- 2. Loop for remaining pages ---
        for (let page = 2; page <= totalPages; page++) {
            // console.log(`Fetching page ${page} of ${totalPages}...`);
            const params = { "page": page, "pageSize": pageSize, "search": '' };
            // FIXED BUG: Use the correct API ID in the loop
            const response = await window.loomeApi.runApiRequest(API_DATASOURCETYPE_ID, params);
            const parsed = safeParseJson(response);
            if (parsed && parsed.Results) {
                allResults = allResults.concat(parsed.Results);
            }
        }

        // console.log(`Successfully fetched a total of ${allResults.length} data source types.`);
        return allResults;

    } catch (error) {
        console.error("An error occurred while fetching data source types:", error);
        return []; // Return empty array on failure
    }
}

/**
 * Safely parses a response that might be a JSON string or an object.
 * @param {string | object} response The API response.
 * @returns {object}
 */
function safeParseJson(response) {
    return typeof response === 'string' ? JSON.parse(response) : response;
}


async function renderPlatformAdminMetaDataPage() {

    const allTypesArray = await getAllDataSourceTypes();
    const typeNamesList = allTypesArray.map(item => item.Name);
    // Populate global list for use when rendering each accordion
    dataSourceTypeNames = typeNamesList.slice();
    // Populate id/name list and lookup map
    dataSourceTypesList = allTypesArray.map(t => ({ id: t.DataSourceTypeID, name: t.Name }));
    dataSourceTypeIdToName = new Map(dataSourceTypesList.map(d => [String(d.id), d.name]));

    // --- 1. Define the table configuration ---
    // (Moved outside the try block so it's accessible to fetchAndRenderPage)
    const tableConfig = {
                headers: [
                    { label: "Name", key: "Name", widthClass: "w-4/12", className: "overflow-hidden",
                      render: (value) => `<span style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${(value||'').replace(/"/g,'&quot;')}">${value||''}</span>`
                    },
                    { label: "Description", key: "Description", widthClass: "w-6/12", className: "overflow-hidden",
                      render: (value) => `<span style="display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis;word-break:break-word;overflow-wrap:break-word;" title="${(value||'').replace(/"/g,'&quot;')}">${value||''}</span>`
                    },
                    {
                        label: "Active",
                        key: "IsActive",
                        render: (value) => value == 1 ? 'Yes' : 'No'
                    },
                    { key: 'Details', label: '', widthClass: 'w-12', 
                      render: () => `<div style="display:flex;justify-content:flex-end;"><svg class="chevron-icon h-5 w-5 text-gray-500" style="width:20px;height:20px;flex-shrink:0;color:#6b7280;" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clip-rule="evenodd" /></svg></div>`
                    }
                ]
    };
        

    // --- 2. Set up Event Listeners ---
    // The search input now calls fetchAndRenderPage
    searchInput.addEventListener('input', () => {
        // When a new search is performed, always go back to page 1
        fetchAndRenderPage(tableConfig, 1, searchInput.value);
    });

    // The pagination container now calls fetchAndRenderPage
    const paginationContainer = document.getElementById('pagination-controls');
    paginationContainer.addEventListener('click', (event) => {
        const button = event.target.closest('button[data-page]');
        if (!button || button.disabled) {
            return;
        }
        const newPage = parseInt(button.dataset.page, 10);
        // console.log('newPage')
        // console.log(newPage)
        // Fetch the new page, preserving the current search term
        fetchAndRenderPage(tableConfig, newPage, searchInput.value);
    });

    paginationContainer.addEventListener('keydown', (event) => {
        // Only act if the user pressed Enter and the target is our input
        if (event.key === 'Enter' && event.target.id === 'page-input') {
            const inputElement = event.target;
            const newPage = parseInt(inputElement.value, 10);

            // Validate the input
            if (newPage >= 1 && newPage <= totalPages) {
                fetchAndRenderPage(tableConfig, newPage, searchInput.value);
            } else {
                // If invalid, show a message and reset the input to the current page
                showToast(`Please enter a page number between 1 and ${totalPages}.`, 'error');
                inputElement.value = currentPage; 
            }
        }
    });

    

    const addMetaDataBtn = document.querySelector('#addMetaDataBtn');;
    if (addMetaDataBtn) {
        addMetaDataBtn.addEventListener('click', () => {
            // Pass the full type objects so AddMetadata can use real IDs (DataSourceTypeID)
            AddMetadata(allTypesArray);
        });
    }
    const saveButton = document.getElementById('modal-save-add-metadata-button');
    const handleSaveClick = async () => {
        // Get the modal instance at the time of clicking (not during page load)
        const modalInstance = bootstrap.Modal.getInstance(document.getElementById('addMetaDataModal'));
        
        const form = document.getElementById('addMetaDataForm');
        
        if (!form.checkValidity()) {
            form.classList.add('was-validated');
            // console.log("Form is invalid. Aborting save.");
            return;
        }

        const payload = getMetaDataFormData(form);
        
        // Validate required fields: Name and at least one Data Source Type
        const rawName = form.querySelector('#metaDataName')?.value || '';
        const rawDesc = form.querySelector('#metaDataDescription')?.value || '';
        if (containsInvalidChars(rawName)) {
            showToast('Special characters are not allowed in the Name.', 'error');
            return;
        }
        if (!payload || !payload.name || String(payload.name).trim() === '') {
            showToast('Name is required.', 'error');
            return;
        }
        if (containsInvalidChars(rawDesc)) {
            showToast('Special characters are not allowed in the Description.', 'error');
            return;
        }
        // console.log("Data gathered from form:", payload);
        
        saveButton.disabled = true;
        saveButton.innerHTML = `
            <span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
            Saving...
        `;

        try {

            const response = await window.loomeApi.runApiRequest(API_ADD_METADATA, payload);
            // console.log("RESPONSE: ", response)

            // Check for error response (e.g. 400 Bad Request)
            const parsed = safeParseJson(response);
            const apiErr = extractApiError(parsed);
            if (apiErr) {
                console.error('API error:', apiErr);
                throw new Error(apiErr);
            }
            if (parsed && parsed.status && parsed.status >= 400) {
                throw new Error(parsed.message || 'Server returned an error.');
            }

            showToast('Meta Data created successfully!');
            
            // This should now work!
            modalInstance.hide();
            
            // Optional: Refresh the table to show the new item
            await fetchAndRenderPage(tableConfig, 1, '');
            
        } catch (error) {
            console.error("API call failed:", error);
            showToast(`Error: ${error.message || 'Failed to save data.'}`, 'error');
        } finally {
            saveButton.disabled = false;
            saveButton.innerHTML = 'Save';
        }
    };

    // --- 6. Add the event listener ---
    // This tells the browser: "When a 'click' happens on 'saveButton', run the 'handleSaveClick' function."
    saveButton.addEventListener('click', handleSaveClick);
    

    // --- 3. Initial Page Load ---
    // Make the first call to fetch page 1 with no search term.
    await fetchAndRenderPage(tableConfig, 1, '');
}


renderPlatformAdminMetaDataPage();